<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Bouncing Balls in a Rotating Hexagon</title>
<style>
  body{margin:0;background:#111;overflow:hidden;}
  canvas{display:block;margin:auto;background:#222;}
</style>
</head>
<body>
<canvas id="c"></canvas>
<script>
(() => {
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = 800;
  const H = canvas.height = 600;

  const BALL_COUNT = 10;
  const BALL_RADIUS = 12;
  const GRAVITY = 0.25;
  const FRICTION = 0.998;
  const HEX_RADIUS = 250;
  const ROT_SPEED = 0.001; // radians per frame

  // create balls with random positions & colors
  const balls = [];
  for (let i = 0; i < BALL_COUNT; i++) {
    balls.push({
      x: W/2 + (Math.random()*2-1)*100,
      y: H/2 + (Math.random()*2-1)*100,
      vx: (Math.random()*2-1)*3,
      vy: (Math.random()*2-1)*3,
      r: BALL_RADIUS,
      color: `hsl(${Math.random()*360},80%,60%)`
    });
  }

  let angle = 0; // current rotation of hexagon

  // compute hexagon vertices (clockwise) for a given rotation
  function getHexVertices(rot) {
    const verts = [];
    for (let i = 0; i < 6; i++) {
      const a = rot + i * Math.PI/3;
      verts.push({
        x: W/2 + HEX_RADIUS * Math.cos(a),
        y: H/2 + HEX_RADIUS * Math.sin(a)
      });
    }
    return verts;
  }

  // reflect velocity against a normalized outward normal n
  function reflect(vx, vy, nx, ny) {
    const dot = vx*nx + vy*ny;
    return [vx - 2*dot*nx, vy - 2*dot*ny];
  }

  // main loop
  function update() {
    angle += ROT_SPEED;
    const verts = getHexVertices(angle);
    const edges = [];
    for (let i = 0; i < 6; i++) {
      const p1 = verts[i];
      const p2 = verts[(i+1)%6];
      const dx = p2.x - p1.x;
      const dy = p2.y - p1.y;
      // outward normal for clockwise vertices
      const nx = dy;
      const ny = -dx;
      const len = Math.hypot(nx, ny);
      edges.push({p1,p2,nx:nx/len,ny:ny/len});
    }

    // ball‑ball collisions
    for (let i = 0; i < BALL_COUNT; i++) {
      for (let j = i+1; j < BALL_COUNT; j++) {
        const a = balls[i], b = balls[j];
        const dx = b.x - a.x, dy = b.y - a.y;
        const dist = Math.hypot(dx, dy);
        const minDist = a.r + b.r;
        if (dist < minDist) {
          // normal
          const nx = dx/dist, ny = dy/dist;
          // relative velocity
          const rvx = b.vx - a.vx, rvy = b.vy - a.vy;
          const rel = rvx*nx + rvy*ny;
          if (rel < 0) {
            // simple equal‑mass elastic response
            const impulse = -2 * rel / 2;
            a.vx -= impulse * nx;
            a.vy -= impulse * ny;
            b.vx += impulse * nx;
            b.vy += impulse * ny;
          }
          // separate overlap
          const overlap = minDist - dist;
          a.x -= nx * overlap/2;
          a.y -= ny * overlap/2;
          b.x += nx * overlap/2;
          b.y += ny * overlap/2;
        }
      }
    }

    // ball‑wall collisions & physics integration
    for (const b of balls) {
      // gravity
      b.vy += GRAVITY;

      // move
      b.x += b.vx;
      b.y += b.vy;

      // friction (air)
      b.vx *= FRICTION;
      b.vy *= FRICTION;

      // collision with rotating hexagon edges
      for (const e of edges) {
        const {p1, nx, ny} = e;
        // vector from p1 to ball centre
        const px = b.x - p1.x;
        const py = b.y - p1.y;
        // signed distance to edge (positive outward)
        const dist = px*nx + py*ny;
        if (dist < b.r) {
          // check if moving outward
          const vn = b.vx*nx + b.vy*ny;
          if (vn > 0) {
            const [rvx, rvy] = reflect(b.vx, b.vy, nx, ny);
            b.vx = rvx;
            b.vy = rvy;
            // push ball inside
            const correction = b.r - dist;
            b.x -= nx * correction;
            b.y -= ny * correction;
          }
        }
      }
    }

    // draw
    ctx.clearRect(0,0,W,H);

    // draw rotating hexagon
    ctx.strokeStyle = '#888';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(verts[0].x, verts[0].y);
    for (let i = 1; i < 6; i++) ctx.lineTo(verts[i].x, verts[i].y);
    ctx.closePath();
    ctx.stroke();

    // draw balls
    for (const b of balls) {
      ctx.fillStyle = b.color;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI*2);
      ctx.fill();
    }

    requestAnimationFrame(update);
  }

  // start animation
  requestAnimationFrame(update);
})();
</script>
</body>
</html>
```

The script continuously updates each ball’s velocity with gravity and friction, checks and resolves collisions with other balls and the rotating hexagon’s edges, and redraws everything on the canvas each animation frame.
